def candidates(g):
    cells={(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==8}
    cs={p:[] for p in cells}
    h,w=len(g),len(g[0])
    for r in range(h-1):
      for c in range(w-1):
        square={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
        if square<=cells:
          for p in square: cs[p].append((1,square))
        for miss,col in [((r,c),2),((r+1,c),3),((r,c+1),4),((r+1,c+1),5)]:
          tile={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}-{miss}
          if tile<=cells:
            for p in tile: cs[p].append((col,tile))
    return cells,cs

def covers(g,limit=100000):
